  "/sounds/technical-drawing/isometric/what-is-isometric.mp3": {
    src: "/sounds/technical-drawing/isometric/what-is-isometric.mp3",
    duration: 35.568,
    lines: [
    {
      start: 0,
      end: 3.147,
      text: "Last lesson we cut a block into three flat views.",
      words: [
        {"t":0,"d":0.458,"w":"Last"},
        {"t":0.458,"d":0.381,"w":"lesson"},
        {"t":0.84,"d":0.219,"w":"we"},
        {"t":1.059,"d":0.219,"w":"cut"},
        {"t":1.278,"d":0.42,"w":"a"},
        {"t":1.699,"d":0.219,"w":"block"},
        {"t":1.918,"d":0.381,"w":"into"},
        {"t":2.299,"d":0.219,"w":"three"},
        {"t":2.518,"d":0.219,"w":"flat"},
        {"t":2.737,"d":0.219,"w":"views."},
      ],
    },
    {
      start: 3.147,
      end: 6.445,
      text: "Today we do the opposite. We draw the whole block as one picture.",
      words: [
        {"t":3.147,"d":0.271,"w":"Today"},
        {"t":3.418,"d":0.155,"w":"we"},
        {"t":3.573,"d":0.155,"w":"do"},
        {"t":3.729,"d":0.155,"w":"the"},
        {"t":3.884,"d":0.386,"w":"opposite."},
        {"t":4.27,"d":0.155,"w":"We"},
        {"t":4.425,"d":0.155,"w":"draw"},
        {"t":4.581,"d":0.155,"w":"the"},
        {"t":4.736,"d":0.155,"w":"whole"},
        {"t":4.892,"d":0.76,"w":"block"},
        {"t":5.652,"d":0.155,"w":"as"},
        {"t":5.807,"d":0.155,"w":"one"},
        {"t":5.963,"d":0.271,"w":"picture."},
      ],
    },
    {
      start: 6.445,
      end: 8.007,
      text: "This is called isometric drawing.",
      words: [
        {"t":6.445,"d":0.129,"w":"This"},
        {"t":6.574,"d":0.129,"w":"is"},
        {"t":6.704,"d":0.225,"w":"called"},
        {"t":6.929,"d":0.623,"w":"isometric"},
        {"t":7.551,"d":0.225,"w":"drawing."},
      ],
    },
    {
      start: 8.007,
      end: 11.438,
      text: "Isometric means equal measure. Iso is equal. Metric is measure.",
      words: [
        {"t":8.007,"d":0.582,"w":"Isometric"},
        {"t":8.589,"d":0.181,"w":"means"},
        {"t":8.77,"d":0.314,"w":"equal"},
        {"t":9.084,"d":0.314,"w":"measure."},
        {"t":9.399,"d":0.314,"w":"Iso"},
        {"t":9.713,"d":0.181,"w":"is"},
        {"t":9.894,"d":0.314,"w":"equal."},
        {"t":10.208,"d":0.314,"w":"Metric"},
        {"t":10.522,"d":0.181,"w":"is"},
        {"t":10.703,"d":0.314,"w":"measure."},
      ],
    },
    {
      start: 11.438,
      end: 20.455,
      text: "It has three directions, and only three.",
      words: [
        {"t":11.438,"d":0.118,"w":"It"},
        {"t":11.556,"d":7.806,"w":"has"},
        {"t":19.362,"d":0.118,"w":"three"},
        {"t":19.48,"d":0.293,"w":"directions,"},
        {"t":19.773,"d":0.118,"w":"and"},
        {"t":19.891,"d":0.205,"w":"only"},
        {"t":20.096,"d":0.118,"w":"three."},
      ],
    },
    {
      start: 20.455,
      end: 22.136,
      text: "Height goes straight up. Always straight up, never slanted.",
      words: [
        {"t":20.455,"d":0.135,"w":"Height"},
        {"t":20.59,"d":0.135,"w":"goes"},
        {"t":20.726,"d":0.135,"w":"straight"},
        {"t":20.861,"d":0.135,"w":"up."},
        {"t":20.996,"d":0.236,"w":"Always"},
        {"t":21.232,"d":0.135,"w":"straight"},
        {"t":21.368,"d":0.135,"w":"up,"},
        {"t":21.503,"d":0.236,"w":"never"},
        {"t":21.739,"d":0.236,"w":"slanted."},
      ],
    },
    {
      start: 22.136,
      end: 23.896,
      text: "Length goes up to the right, at thirty degrees.",
      words: [
        {"t":22.136,"d":0.147,"w":"Length"},
        {"t":22.282,"d":0.147,"w":"goes"},
        {"t":22.429,"d":0.147,"w":"up"},
        {"t":22.576,"d":0.147,"w":"to"},
        {"t":22.723,"d":0.147,"w":"the"},
        {"t":22.869,"d":0.147,"w":"right,"},
        {"t":23.016,"d":0.147,"w":"at"},
        {"t":23.163,"d":0.255,"w":"thirty"},
        {"t":23.418,"d":0.255,"w":"degrees."},
      ],
    },
    {
      start: 23.896,
      end: 25.563,
      text: "Depth goes up to the left, at thirty degrees.",
      words: [
        {"t":23.896,"d":0.113,"w":"Depth"},
        {"t":24.009,"d":0.113,"w":"goes"},
        {"t":24.122,"d":0.113,"w":"up"},
        {"t":24.235,"d":0.113,"w":"to"},
        {"t":24.347,"d":0.113,"w":"the"},
        {"t":24.46,"d":0.113,"w":"left,"},
        {"t":24.573,"d":0.113,"w":"at"},
        {"t":24.686,"d":0.196,"w":"thirty"},
        {"t":24.882,"d":0.196,"w":"degrees."},
      ],
    },
    {
      start: 25.563,
      end: 35.568,
      text: "Thirty degrees. That is exactly what your set square gives you, so you never guess.",
      words: [
        {"t":25.563,"d":0.336,"w":"Thirty"},
        {"t":25.899,"d":0.336,"w":"degrees."},
        {"t":26.236,"d":0.193,"w":"That"},
        {"t":26.429,"d":0.193,"w":"is"},
        {"t":26.622,"d":0.824,"w":"exactly"},
        {"t":27.446,"d":0.193,"w":"what"},
        {"t":27.639,"d":0.391,"w":"your"},
        {"t":28.03,"d":0.193,"w":"set"},
        {"t":28.223,"d":0.193,"w":"square"},
        {"t":28.416,"d":6.044,"w":"gives"},
        {"t":34.46,"d":0.193,"w":"you,"},
        {"t":34.653,"d":0.193,"w":"so"},
        {"t":34.846,"d":0.193,"w":"you"},
        {"t":35.039,"d":0.336,"w":"never"},
        {"t":35.375,"d":0.193,"w":"guess."},
      ],
    },
    ],
  },
